theorem clamp_in_range (f : Field) (v : Std.I32) {lo hi r}
    (hr : range f = ok (lo, hi)) (hc : clamp_field f v = ok r) :
    lo.val ≤ r.val ∧ r.val ≤ hi.val

theorem clamp_keeps_in_range (f : Field) (v : Std.I32) {lo hi}
    (hr : range f = ok (lo, hi)) (h1 : lo.val ≤ v.val) (h2 : v.val ≤ hi.val) :
    clamp_field f v = ok v

Wifi.kernel_code:
pub enum Wifi {
    /// Store this name (or, without one, the stored config unchanged) and
    /// restart into it: `200 restarting`.
    StoreAndRestart,
    /// An empty name or one over 32 bytes: `400`, nothing stored, no
    /// restart (upstream stores an empty name).
    Refuse,
}

range.kernel_code:
pub fn range(f: Field) -> (i32, i32) {
    match f {
        Field::PupilLength => (20, 120),
        Field::WiggleAmp => (0, 400),
        Field::BlinkInterval => (60, 600),
        Field::EyeRed => (0, 31),
        Field::EyeGreen => (0, 63),
        Field::EyeBlue => (0, 31),
        Field::SoundThreshold => (10, 400),
        _ => (0, 100),
    }
}

expression_ok.kernel_code:
pub fn expression_ok(code: i32) -> bool {
    // Two ranges (comparisons extract to Lean as plain inequalities).
    if code >= 1 && code <= 5 {
        true
    } else {
        code >= 7 && code <= 10
    }
}

