wifi_set.kernel_code:
pub fn wifi_set(given: bool, len: u32) -> Wifi {
    if !given {
        Wifi::StoreAndRestart
    } else if len == 0 || len > SSID_MAX_LEN {
        Wifi::Refuse
    } else {
        Wifi::StoreAndRestart
    }
}

