ota_start.kernel_code:
pub fn ota_start(post: bool, busy: bool, has_target: bool, total: u32, max_size: u32) -> OtaStart {
    if !post {
        OtaStart::MethodNotAllowed
    } else if busy {
        OtaStart::Conflict
    } else if !has_target {
        OtaStart::NoTarget
    } else if total == 0 || total > max_size {
        OtaStart::BadRequest
    } else {
        OtaStart::Stream
    }
}

OtaStart.kernel_code:
pub enum OtaStart {
    MethodNotAllowed,
    /// Another upload is running.
    Conflict,
    /// No slot to write (the partition table).
    NoTarget,
    /// Empty, or larger than the slot.
    BadRequest,
    /// Stream the image into the slot.
    Stream,
}

clamp_field.kernel_code:
pub fn clamp_field(f: Field, v: i32) -> i32 {
    let (lo, hi) = range(f);
    if v < lo {
        lo
    } else if v > hi {
        hi
    } else {
        v
    }
}

